function verifyGame120(log) {
const cols="ABCDEFGHJ", letters="abcdefghi";
function point(p){return (9-Number(p.slice(1)))*9+cols.indexOf(p[0]);}
function coord(i){return cols[i%9]+(9-Math.floor(i/9));}
function adj(i){const r=Math.floor(i/9),c=i%9;return [[r-1,c],[r+1,c],[r,c-1],[r,c+1]].filter(([r,c])=>r>=0&&r<9&&c>=0&&c<9).map(([r,c])=>r*9+c);}
function inspectBoard(b){const seen=new Set(),groups=[],regions=[];for(let i=0;i<81;i++){if(seen.has(i))continue;const v=b[i],q=[i],stones=[],lib=new Set(),border=new Set();seen.add(i);while(q.length){const k=q.pop();stones.push(k);for(const n of adj(k)){if(b[n]===v){if(!seen.has(n)){seen.add(n);q.push(n);}}else if(v!=="."){if(b[n]===".")lib.add(n);}else border.add(b[n]);}}if(v===".")regions.push({points:stones.map(coord).sort(),border:[...border].sort()});else groups.push({color:v,stones:stones.map(coord).sort(),liberties:[...lib].map(coord).sort()});}return{board:b.join(""),groups,regions};}
function area(p){let B=p.board.split("").filter(x=>x==="X").length,W=p.board.split("").filter(x=>x==="O").length,bt=0,wt=0,neutral=0;for(const r of p.regions){if(r.border.join("")==="X")bt+=r.points.length;else if(r.border.join("")==="O")wt+=r.points.length;else neutral+=r.points.length;}return{B:B+bt,W:W+wt,blackStones:B,whiteStones:W,blackTerritory:bt,whiteTerritory:wt,neutral,whiteMargin:W+wt+7-B-bt};}
let b=Array(81).fill("."),captures={B:0,W:0},ko=null,moves=[],checks=[],positions=[];
function apply(color,move){const enemy=color==="B"?"O":"X",own=color==="B"?"X":"O";if(move==="pass"){ko=null;}else{const i=point(move);if(b[i]!==".")throw Error("Occupied "+move);if(move===ko)throw Error("Ko "+move);b[i]=own;let dead=[];for(const g of inspectBoard(b).groups){if(g.color===enemy&&!g.liberties.length)dead.push(...g.stones);}for(const p of dead)b[point(p)]=".";captures[color]+=dead.length;const myGroup=inspectBoard(b).groups.find(g=>g.color===own&&g.stones.includes(move));if(!myGroup.liberties.length)throw Error("Suicide "+move);ko=dead.length===1&&myGroup.stones.length===1&&myGroup.liberties.length===1?dead[0]:null;}moves.push({number:moves.length+1,color,move});positions.push({afterMove:moves.length,inspection:inspectBoard(b),captures:{...captures},ko});}
