const cols="ABCDEFGHJ", point=p=>(9-Number(p.slice(1)))*9+cols.indexOf(p[0]);
let b=Array(81).fill("."),moves=[],checks=[],positions=[],captures={B:0,W:0},ko=null;
function apply(color,move){
if(move==="pass")ko=null;
else{let i=point(move),own=color==="B"?"X":"O",enemy=color==="B"?"O":"X";if(b[i]!==".")throw Error("Occupied "+move);if(move===ko)throw Error("Ko "+move);b[i]=own;
let dead=inspect(b).groups.filter(g=>g.color===enemy&&!g.liberties.length).flatMap(g=>g.stones);for(let p of dead)b[point(p)]=".";captures[color]+=dead.length;
let me=inspect(b).groups.find(g=>g.color===own&&g.stones.includes(move));if(!me.liberties.length)throw Error("Suicide "+move);ko=dead.length===1&&me.stones.length===1&&me.liberties.length===1?dead[0]:null;}
moves.push({number:moves.length+1,color,move});positions.push({after:moves.length,board:b.join(""),captures:{...captures},ko,inspection:inspect(b)});
}
for(let s of log.raw){let {b:shown,t}=parse(s.response);
if(s.kind==="play"){let mine=t.match(/You played ([A-J][1-9])\./),reply=t.match(/Your opponent played ([A-J][1-9])\./);
if(mine)apply("B",mine[1]);else if(t.includes("You passed."))apply("B","pass");else throw Error("No own move");
if(reply)apply("W",reply[1]);else if(t.includes("Your opponent passed."))apply("W","pass");else throw Error("No reply");}
let cap=t.match(/Captured by Black: (\d+); by White: (\d+)/),next=t.match(/Move number: (\d+)/),km=t.match(/Ko point: ([A-J][1-9]|none)/);
let c={kind:s.kind,after:moves.length,boardMatches:shown.join("")===b.join(""),capturesMatch:!!cap&&+cap[1]===captures.B&&+cap[2]===captures.W,nextMatches:!!next&&+next[1]===moves.length+1,koMatches:!!km&&km[1]===(ko||"none")};
if(Object.values(c).includes(false))throw Error(JSON.stringify(c));checks.push(c);
}
let displayed=inspect(b),removed=b.slice(),deadBlack=["G8","G9","H8"];for(let p of deadBlack){if(removed[point(p)]!=="X")throw Error("Not black "+p);removed[point(p)]=".";}
let scored=inspect(removed),letters="abcdefghi",sgf="(;GM[1]FF[4]CA[UTF-8]SZ[9]RU[Chinese]KM[7]PB[Codex]PW[KataGo human-style 20k]DT[2026-10-06]RE[W+6]C[Game 121. Physical captures 0/0. Corner three inferred dead remain displayed; no official dead list.]"+moves.map(m=>";"+m.color+"["+(m.move==="pass"?"":letters[point(m.move)%9]+letters[Math.floor(point(m.move)/9)])+"]").join("")+")\n";
return{moves,checks,positions,displayed,inferredRemoval:{deadBlack,officialDeadList:false,inspection:scored},sgf,limitations:"Actual-history replay only. No future search, recommendation or engine. After-own-move inspections retrospective; live inspections after36/42."};
}
